error-handling.example:
// Sentinel for simple classification
var (
    ErrNotFound  = errors.New("not found")
    ErrDuplicate = errors.New("duplicate")
)

// Structured error for fields the caller needs to extract
type QueryError struct {
    Table string
    Op    string
    Err   error
}

func (e *QueryError) Error() string {
    return fmt.Sprintf("%s on %s: %v", e.Op, e.Table, e.Err)
}

func (e *QueryError) Unwrap() error { return e.Err }

// Wrapping with %w: caller can use errors.Is/As
func fetchUser(ctx context.Context, id string) (*User, error) {
    row, err := db.QueryRowContext(ctx, "SELECT * FROM users WHERE id = $1", id)
    if err != nil {
        return nil, fmt.Errorf("fetch user %s: %w", id, err)
    }
    if row == nil {
        return nil, fmt.Errorf("fetch user %s: %w", id, ErrNotFound)
    }
    ...
}

// Caller
u, err := fetchUser(ctx, id)
if errors.Is(err, ErrNotFound) {
    // handle not found
}
var qErr *QueryError
if errors.As(err, &qErr) {
    log.Printf("query failed on table %s", qErr.Table)
}

context-rules.example:
// WRONG: context stored in struct
type UserService struct {
    ctx context.Context   // don't do this
    db  *sql.DB
}

// RIGHT: pass context to each method
type UserService struct {
    db *sql.DB
}

func (s *UserService) GetUser(ctx context.Context, id string) (*User, error) {
    row := s.db.QueryRowContext(ctx, "SELECT * FROM users WHERE id = $1", id)
    // ctx is propagated, not stored
    ...
}

// WRONG: ignoring the received context
func (s *UserService) SaveUser(ctx context.Context, u *User) error {
    return s.db.ExecContext(context.Background(), "INSERT ...", u.ID)  // lost the deadline!
}

// RIGHT: propagate the received context
func (s *UserService) SaveUser(ctx context.Context, u *User) error {
    _, err := s.db.ExecContext(ctx, "INSERT ...", u.ID)
    return err
}

goroutine-lifecycle.example:
// Documented lifetime
func startWorker(ctx context.Context, jobs <-chan Job) {
    // This goroutine runs until ctx is cancelled or jobs is closed.
    go func() {
        for {
            select {
            case <-ctx.Done():
                return
            case job, ok := <-jobs:
                if !ok {
                    return
                }
                processJob(job)
            }
        }
    }()
}

// Test goroutine: t.Error not t.Fatal
func TestConcurrentFetch(t *testing.T) {
    var wg sync.WaitGroup
    wg.Add(3)
    for i := 0; i < 3; i++ {
        go func(n int) {
            defer wg.Done()
            result, err := fetchItem(n)
            if err != nil {
                t.Errorf("fetchItem(%d): %v", n, err)  // t.Error, not t.Fatal
                return
            }
            if result == nil {
                t.Errorf("fetchItem(%d) returned nil", n)
            }
        }(i)
    }
    wg.Wait()  // wait before test returns
}

interface-design.example:
// Small interface defined by the consumer (userservice package)
// The implementation (postgres package) doesn't know about this interface.
package userservice

type UserStore interface {
    GetUser(ctx context.Context, id string) (*User, error)
    SaveUser(ctx context.Context, u *User) error
}

type Service struct {
    store UserStore   // accepts the interface
}

// Concrete return type — callers get full detail
func NewService(store UserStore) *Service {   // returns *Service, not an interface
    return &Service{store: store}
}

// For testing: a fake that satisfies UserStore
type fakeUserStore struct {
    users map[string]*User
}

func (f *fakeUserStore) GetUser(_ context.Context, id string) (*User, error) {
    u, ok := f.users[id]
    if !ok {
        return nil, ErrNotFound
    }
    return u, nil
}

init-function.example:
// WRONG: init() doing setup that should be explicit
func init() {
    db, err := sql.Open("postgres", os.Getenv("DATABASE_URL"))
    if err != nil {
        log.Fatal(err)  // can't return an error, so log.Fatal is the only option
    }
    globalDB = db     // global state set in init — hard to test
}

// RIGHT: explicit setup function that returns an error
func setupDatabase(connStr string) (*sql.DB, error) {
    db, err := sql.Open("postgres", connStr)
    if err != nil {
        return nil, fmt.Errorf("open database: %w", err)
    }
    if err := db.Ping(); err != nil {
        return nil, fmt.Errorf("ping database: %w", err)
    }
    return db, nil
}

// Acceptable: driver registration side effect
import _ "github.com/lib/pq"   // registers postgres driver

func init() {
    // Acceptable: register a codec at startup
    gob.Register(&MyType{})
}

defer-patterns.example:
// WRONG: defer inside a loop — files stay open until the function returns
func processFiles(paths []string) error {
    for _, path := range paths {
        f, err := os.Open(path)
        if err != nil {
            return err
        }
        defer f.Close()   // runs at the end of processFiles, not each iteration
        process(f)
    }
    return nil
}

// RIGHT: extract to a helper so defer runs per iteration
func processFiles(paths []string) error {
    for _, path := range paths {
        if err := processFile(path); err != nil {
            return err
        }
    }
    return nil
}

func processFile(path string) error {
    f, err := os.Open(path)
    if err != nil {
        return err
    }
    defer f.Close()   // runs when processFile returns — correct
    return process(f)
}

struct-embedding.example:
// Good: embed sync.Mutex to get locking behavior
type SafeCounter struct {
    sync.Mutex    // promoted Lock/Unlock methods
    count int
}

func (c *SafeCounter) Increment() {
    c.Lock()
    defer c.Unlock()
    c.count++
}

// Good: embed interface in test stub to satisfy the full interface cheaply
type stubStore struct {
    UserStore    // embedded interface — nil implementations panic if called
}

// Only override the methods the test needs
func (s *stubStore) GetUser(ctx context.Context, id string) (*User, error) {
    return &User{ID: id, Name: "test"}, nil
}

// Careful: embedding exposes all methods — only do this when you want them all
type LoggedDB struct {
    *sql.DB    // ALL DB methods become methods of LoggedDB
    logger *slog.Logger
}

options-pattern.example:
// Option struct: self-documenting call site
type ReplicationOptions struct {
    PrimaryRegions      []string
    ReadonlyRegions     []string
    ReplicationInterval time.Duration
    Workers             int
}

func EnableReplication(ctx context.Context, cfg *Config, opts ReplicationOptions) error { ... }

// Call site is readable:
EnableReplication(ctx, cfg, ReplicationOptions{
    PrimaryRegions:      []string{"us-east-1"},
    ReplicationInterval: 5 * time.Minute,
})

// Functional options: good when most callers use defaults
type serverOption func(*serverConfig)

func WithTimeout(d time.Duration) serverOption {
    return func(c *serverConfig) { c.timeout = d }
}

func WithMaxConnections(n int) serverOption {
    return func(c *serverConfig) { c.maxConns = n }
}

func NewServer(addr string, opts ...serverOption) *Server {
    cfg := &serverConfig{timeout: 30 * time.Second, maxConns: 100}
    for _, opt := range opts {
        opt(cfg)
    }
    return &Server{addr: addr, cfg: cfg}
}

// Call site: zero overhead for default users
s1 := NewServer(":8080")
s2 := NewServer(":8080", WithTimeout(60*time.Second), WithMaxConnections(500))

panic-recover.example:
// Internal panic-as-flow-control, recovered at the package boundary
type parseError struct{ msg string }

func ParseConfig(input string) (_ *Config, err error) {
    defer func() {
        if p := recover(); p != nil {
            if pe, ok := p.(*parseError); ok {
                err = fmt.Errorf("parse config: %s", pe.msg)
            } else {
                panic(p)  // re-panic anything not ours
            }
        }
    }()
    return parse(input), nil  // internal code may panic(*parseError)
}

// Package-level must: acceptable for compile-time constants
var validEmail = regexp.MustCompile(`^[^@]+@[^@]+\.[^@]+$`)

// main(): log.Fatal over panic
func main() {
    cfg, err := loadConfig()
    if err != nil {
        log.Fatalf("failed to load config: %v", err)  // not panic
    }
}

testing-practices.example:
// t.Helper: failure points to caller, not inside assertNoError
func assertNoError(t *testing.T, err error) {
    t.Helper()   // without this, the failure points here instead of the caller
    if err != nil {
        t.Fatalf("unexpected error: %v", err)
    }
}

func TestOrderProcessing(t *testing.T) {
    tests := []struct {
        name    string
        order   Order
        wantErr bool
    }{
        {"valid order", Order{Total: 100}, false},
        {"zero total", Order{Total: 0}, true},
    }
    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {  // subtest: independent, named
            err := processOrder(tt.order)
            if (err != nil) != tt.wantErr {
                t.Errorf("processOrder() error = %v, wantErr %v", err, tt.wantErr)
                // t.Error: test continues to next case in the table
            }
        })
    }
}

// Test helper package
package paymenttest

// AlwaysCharges succeeds every charge operation.
type AlwaysCharges struct{}

func (AlwaysCharges) Charge(_ context.Context, _ Amount) error { return nil }

// AlwaysDeclines fails every charge operation.
type AlwaysDeclines struct{}

func (AlwaysDeclines) Charge(_ context.Context, _ Amount) error {
    return errors.New("card declined")
}
